urlset:
{% for path in ["/", "/agreements/", "/organisations/", "/datasets/", "/changes/", "/downloads/", "/about/"] %}
  {{ meta.site_url }}{{ meta.base_path }}{{ path }}
{% endfor %}
{% for a in agreements %}
  {{ meta.site_url }}{{ meta.base_path }}/agreements/{{ a.slug }}/
{% endfor %}
{% for o in organisations %}
  {{ meta.site_url }}{{ meta.base_path }}/organisations/{{ o.slug }}/
{% endfor %}
{% for d in datasets %}
  {{ meta.site_url }}{{ meta.base_path }}/datasets/{{ d.slug }}/
{% endfor %}
